      "overview": "제목 Werwulf는 현대 영어 단어 werewolf(늑대인간)를 일부러 고어(古語)식으로 표기한 것이다. *wer-*는 고대 영어에서 \"사람(man)\"을 뜻하고, 여기에 wulf(늑대)가 붙어 \"사람-늑대\", 즉 늑대인간을 의미한다. 이 작품은 영어권 영화이고 시대극 대사도 중세 영어 기반이므로, 발음은 영어식 /w/ 소리를 따라 \"웨어울프\"가 된다. 반면 \"베어볼프\"는 독일어 Werwolf의 발음(대략 [ˈveːɐ̯vɔlf])에 가깝다. 독일어에서는 철자 w가 /v/로 소리 나기 때문에 \"베어볼프\"처럼 들리는 것인데, 이 영화는 독일어 작품이 아니므로 여기에는 해당하지 않는다. 굳이 고대 영어 원음까지 따진다면 wer의 자음은 여전히 /w/ 계열이라 \"베—\"로 시작하지는 않는다.",
