      "overview": "화려한 장식과 긴 복도를 갖춘 호텔에서, 한 남자가 여인에게 다가와 지난해 두 사람이 사랑했다고 말한다. 그는 함께 떠나자는 자신의 청에 여인이 일 년을 기다려 달라고 답했으며, 이제 그 약속을 지키러 왔다고 주장한다. 그러나 여인은 그를 만난 적조차 없다며 부인하고, 남자가 떠올리는 장소와 대화에도 쉽게 동의하지 않는다. 여인의 남편처럼 보이는 또 다른 남자는 곁을 맴돌며 게임에서 거듭 상대를 이기지만, 세 사람의 관계는 분명해지지 않는다. 정원과 방, 복도에서 반복되는 대화는 매번 조금씩 달라지고, 지나간 일과 지금 벌어지는 일 사이의 경계도 흐려진다. 기억을 되찾으라는 설득이 계속될수록, 여인이 거부하는 것은 잊어버린 과거일까 아니면 아직 선택하지 않은 미래일까?",
