        "overview": "1961년 겨울의 뉴욕, 포크 가수 르윈 데이비스는 기타를 들고 작은 클럽에서 노래하며 지인들의 소파를 잠자리 삼아 살아간다. 함께 노래하던 동료를 잃은 뒤 내놓은 솔로 음반은 팔리지 않고, 음악을 포기하지 않겠다는 고집만큼 생활은 궁핍해진다. 하룻밤 신세 진 집의 고양이까지 뜻하지 않게 데리고 나오면서, 몸을 누일 곳을 찾는 일도 번거로워진다. 여기에 가까운 사이인 진이 임신 소식을 전하며 책임을 묻자, 르윈은 돈과 인간관계 문제에 동시에 몰린다. 새로운 기회를 붙잡으려 시카고의 음악 관계자를 찾아가기로 한 그는 낯선 동행자들과 차를 타고 길을 나선다. 추위와 자존심, 남겨둔 사람들 사이를 떠도는 르윈에게 이번 여행은 노래로 살아갈 수 있는지 다시 묻는 시간이 된다.",
