        "overview": "전란이 이어지는 일본에서 소년 코타로는 자신을 뒤쫓는 명나라 무사들을 피해 개 토비마루와 함께 도망치고 있다. 버려진 절에 숨은 그는 떠돌이 무사 나나시를 만나지만, 쉽게 남을 믿지 못하는 탓에 낯선 남자의 호의를 경계한다. 추격대의 습격으로 토비마루가 중독되자 코타로는 약을 구하고 목적지에 도착하기 위해 나나시를 호위로 고용한다. 나나시는 뛰어난 솜씨를 지녔으면서도 과거의 상처 때문에 칼집에 묶어 둔 검을 뽑으려 하지 않는다. 소년을 손에 넣으려는 명나라 일행과 그들을 이용하려는 영주의 계산이 얽히고, 강한 상대와 겨루는 데 집착하는 금발 검객이 뒤를 좇는다. 함께 걷는 동안 조금씩 가까워지는 두 사람 앞에, 돈으로 맺은 약속만으로는 감당할 수 없는 위협이 다가온다.",
