        "overview": "전쟁 말기 섬에서 괴수의 습격을 겪은 조종사 시키시마 고이치는 살아남았다는 죄책감을 안고 폐허가 된 도쿄로 돌아온다. 가족과 집을 잃은 그는 노리코와 어린 아키코를 만나 함께 지내며, 바다의 기뢰를 제거하는 일로 삶을 이어 간다. 조금씩 일상을 되찾으려는 사람들 앞에 더욱 거대해진 고질라가 나타나고, 전쟁의 상처가 아물기도 전에 새로운 파괴가 밀려온다. 군대의 보호를 기대하기 어려운 상황에서 배를 모는 동료들과 민간인들은 가진 기술과 장비를 모아 맞설 방법을 찾는다. 고이치에게 눈앞의 위협은 소중한 사람들을 지키는 문제이자, 끝나지 않은 자신의 전쟁을 다시 마주하는 일이 된다. 이제 살아남은 이들은 죽음을 각오하라는 명령 대신 함께 살아갈 방법을 선택해야 한다.",
