        "overview": "아버지의 병환으로 고향에 돌아온 대학생 제프리는 길을 걷다가 풀밭에 버려진 사람의 귀 한쪽을 발견하고 경찰에 신고한다. 사건을 맡은 형사의 딸 샌디에게서 한 여가수의 이름을 들은 그는 멀쩡해 보이던 마을의 이면에 강한 호기심을 느낀다. 제프리는 블루 벨벳을 노래하는 도로시를 찾아가고, 혼자 비밀을 알아내려는 마음에 그녀의 아파트로 몰래 들어간다. 그러나 예상보다 일찍 돌아온 도로시에게 들키면서 관찰자로 남으려던 계획은 흔들리고, 두 사람 사이에는 불안한 긴장이 흐른다. 그때 거칠고 위협적인 남자 프랭크가 들이닥치자 제프리는 옷장 안에 숨어 상상하지 못한 광경을 목격한다. 한 번 들여다본 비밀을 외면할 수 없게 된 그는 호기심과 욕망이 뒤엉킨 위험한 관계에 발을 들인다.",
