        "overview": "십자군 전쟁을 마치고 돌아온 기사 안토니우스 블로크는 페스트가 휩쓴 스웨덴 해변에서 자신을 데리러 온 죽음의 사자를 만난다. 신의 침묵과 삶의 의미에 괴로워하던 그는 아직 끝내지 못한 일이 있다며 목숨을 건 체스 대결을 제안한다. 승부가 이어지는 동안 종자 옌스와 고향으로 향하지만, 길에서 마주치는 사람들 역시 질병과 공포 속에서 구원을 갈망한다. 교회에서도 확신을 얻지 못한 블로크 앞에 광대 요프와 미아 부부, 그리고 어린아이가 나타난다. 소박한 가족과 함께하는 잠깐의 평온은 죽음을 늦추려던 그의 여정에 새로운 바람을 불어넣는다. 마지막 수를 피할 수 없는 기사는 남겨진 시간 안에 자신이 지켜야 할 것이 무엇인지 묻는다.",
