        "overview": "별장에 있는 과학자 크리스 켈빈에게 연구소로부터 비디오 테이프가 전달된다. 연구소는 우주 정거장이 보내온 비디오 테이프를 보며 혹성 솔라리스에게 무슨 일이 벌어지고 있다는 결론을 내리고, 그 정거장에 크리스 켈빈을 보내기로 한 것이다. 우주 정거장에 온 켈빈은 여기에서 두 과학자 스나우토와 사리보리우스를 만난다. 물리학자 기바리안은 이미 자살한 후였다. 켈빈은 여기서 혹성 솔라리스의 생각하는 바다에 대해서 듣게 된다. 혹성 솔라리스에 접근하면 여기에 근접한 사람과 솔라리스가 정신작용을 일으켜 상대방의 기억 깊이 잠겨있는 과거를 물질화한다는 것이다. 이후 독극물 주사로 자살한 크리스 켈빈의 아내가 그의 앞에 물질이 되어 나타나는데..",
